				\usepackage{mathrsfs}
				\usepackage{upgreek}
				\setlength{\oddsidemargin}{-69pt}
				\begin{document}$${\delta }_{n}\left(k\right)=\mathop{{\max }}\limits_{{\mathop{z}\limits^{-}}_{c\left(n\right)}}\big\{P\big({\bar{X}}_{n}={\bar{x}}_{n},{\bar{Z}}_{c\left(n\right)}={\bar{z}}_{c\left(n\right)}{{{{{\rm{|}}}}}}{z}_{n}=k\big)\big\}$$\end{document}δnk=maxz−cnPX¯n=x¯n,Z¯cn=z¯cn∣zn=kand the links between parent-daughter cells as:15\documentclass[12pt]{minimal}
				\usepackage{amsmath}
