				\usepackage{mathrsfs}
				\usepackage{upgreek}
				\setlength{\oddsidemargin}{-69pt}
				\begin{document}$${\delta }_{p\left(n\right),n}\left(k\right)=\mathop{{\max }}\limits_{{\mathop{z}\limits^{-}}_{n}}\big\{P\big({\bar{X}}_{n}={\bar{x}}_{n},{\bar{Z}}_{n}={\bar{z}}_{n}{{{{{\rm{|}}}}}}{z}_{p\left(n\right)}=k\big)\big\}=\mathop{{\max }}\limits_{k}\big\{{\delta }_{n}\left(k\right){T}_{k,k}\big\}$$\end{document}δpn,nk=maxz−nPX¯n=x¯n,Z¯n=z¯n∣zpn=k=maxkδnkTk,k

We initialize from the leaf cells as:16\documentclass[12pt]{minimal}
